#!/usr/bin/env python3
"""Generate rtl/sha256_consts.vh: the SHA-256 initial hash values and round constants (FIPS 180-4 s4.2.2, s5.3.3).

Computed with exact integer arithmetic from the definition (first 32 bits of the fractional parts of the cube /
square roots of the first 64 / 8 primes), then cross-checked against two well-known values.
"""
import os
import sys


def primes(n):
    out, k = [], 2
    while len(out) < n:
        if all(k % p for p in out):
            out.append(k)
        k += 1
    return out


def iroot(x, n):
    """floor of the n-th root of x (integers)."""
    lo, hi = 0, 1
    while hi ** n <= x:
        hi *= 2
    while lo < hi - 1:
        mid = (lo + hi) // 2
        if mid ** n <= x:
            lo = mid
        else:
            hi = mid
    return lo


def constants():
    ps = primes(64)
    k = [iroot(p << 96, 3) & 0xFFFFFFFF for p in ps]          # floor(cbrt(p) * 2**32) mod 2**32
    iv = [iroot(p << 64, 2) & 0xFFFFFFFF for p in ps[:8]]      # floor(sqrt(p) * 2**32) mod 2**32
    return iv, k


def render():
    iv, k = constants()
    assert iv[0] == 0x6A09E667 and k[0] == 0x428A2F98 and k[63] == 0xC67178F2, "constant generation is wrong"
    lines = ["// Generated by tools/gen_consts.py. Do not edit."]
    for i, v in enumerate(iv):
        lines.append("localparam [31:0] IV%d = 32'h%08x;" % (i, v))
    lines.append("function [31:0] sha256_k;")
    lines.append("    input [5:0] t;")
    lines.append("    begin")
    lines.append("        case (t)")
    for i, v in enumerate(k):
        lines.append("            6'd%d: sha256_k = 32'h%08x;" % (i, v))
    lines.append("            default: sha256_k = 32'h00000000;")
    lines.append("        endcase")
    lines.append("    end")
    lines.append("endfunction")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    path = os.path.join(root, "rtl", "sha256_consts.vh")
    text = render()
    if "--check" in sys.argv:
        sys.exit(0 if open(path).read() == text else 1)
    open(path, "w").write(text)
    print("wrote", path)
